/**
 * Asset labels with QR code: label formats, sheet layout, QR payloads and
 * the printable HTML document. Pure functions, the QR SVG is generated by
 * the caller (lazy import of `qrcode`) and passed in.
 */

/** URL scheme of the nextDesk app (bundle identifier). */
export const APP_SCHEME = "ch.grossict.nextdesk";

export type LabelFormatId =
  "avery-l7651" | "avery-3474" | "avery-l7163" | "roll-62x29" | "roll-62x100";

export type LabelFormat = {
  id: LabelFormatId;
  name: string;
  description: string;
  kind: "sheet" | "roll";
  pageWidthMm: number;
  pageHeightMm: number;
  labelWidthMm: number;
  labelHeightMm: number;
  columns: number;
  rows: number;
  marginTopMm: number;
  marginLeftMm: number;
  /** Distance from one label's left edge to the next one's. */
  pitchXMm: number;
  /** Distance from one label's top edge to the next one's. */
  pitchYMm: number;
};

function sheet(
  id: LabelFormatId,
  name: string,
  description: string,
  label: [number, number],
  grid: [number, number],
  margin: [number, number],
  pitch: [number, number],
): LabelFormat {
  return {
    id,
    name,
    description,
    kind: "sheet",
    pageWidthMm: 210,
    pageHeightMm: 297,
    labelWidthMm: label[0],
    labelHeightMm: label[1],
    columns: grid[0],
    rows: grid[1],
    marginTopMm: margin[0],
    marginLeftMm: margin[1],
    pitchXMm: pitch[0],
    pitchYMm: pitch[1],
  };
}

function roll(
  id: LabelFormatId,
  name: string,
  description: string,
  width: number,
  height: number,
): LabelFormat {
  return {
    id,
    name,
    description,
    kind: "roll",
    pageWidthMm: width,
    pageHeightMm: height,
    labelWidthMm: width,
    labelHeightMm: height,
    columns: 1,
    rows: 1,
    marginTopMm: 0,
    marginLeftMm: 0,
    pitchXMm: width,
    pitchYMm: height,
  };
}

export const LABEL_FORMATS: readonly LabelFormat[] = [
  sheet(
    "avery-l7651",
    "Avery L7651 (A4, 65 Etiketten)",
    "38,1 × 21,2 mm, 5 × 13 pro Bogen – kompakt für Geräte",
    [38.1, 21.2],
    [5, 13],
    [10.7, 4.75],
    [40.6, 21.2],
  ),
  sheet(
    "avery-3474",
    "Avery 3474 (A4, 24 Etiketten)",
    "70 × 37 mm, 3 × 8 pro Bogen – mit Logo",
    [70, 37],
    [3, 8],
    [0.5, 0],
    [70, 37],
  ),
  sheet(
    "avery-l7163",
    "Avery L7163 (A4, 14 Etiketten)",
    "99,1 × 38,1 mm, 2 × 7 pro Bogen – gross, z. B. für Racks",
    [99.1, 38.1],
    [2, 7],
    [15.15, 4.65],
    [101.6, 38.1],
  ),
  roll(
    "roll-62x29",
    "Etikettendrucker 62 × 29 mm",
    "Einzeletikett, z. B. Brother DK-11209",
    62,
    29,
  ),
  roll(
    "roll-62x100",
    "Etikettendrucker 62 × 100 mm",
    "Einzeletikett, z. B. Brother DK-11202",
    62,
    100,
  ),
];

export function labelFormat(id: string): LabelFormat {
  return LABEL_FORMATS.find((format) => format.id === id) ?? LABEL_FORMATS[0]!;
}

export function labelsPerPage(format: LabelFormat): number {
  return format.columns * format.rows;
}

export type LabelPosition = {
  page: number;
  column: number;
  row: number;
  xMm: number;
  yMm: number;
};

/**
 * Positions for `count` labels. `skip` leaves the first labels of the first
 * sheet empty, so a partly used sheet can be printed again.
 */
export function layoutLabels(
  format: LabelFormat,
  count: number,
  skip = 0,
): LabelPosition[] {
  const perPage = labelsPerPage(format);
  const offset =
    format.kind === "sheet"
      ? Math.min(Math.max(Math.floor(skip), 0), perPage - 1)
      : 0;
  const positions: LabelPosition[] = [];
  for (let index = 0; index < Math.max(0, Math.floor(count)); index += 1) {
    const slot = index + offset;
    const page = Math.floor(slot / perPage);
    const inPage = slot % perPage;
    const row = Math.floor(inPage / format.columns);
    const column = inPage % format.columns;
    positions.push({
      page,
      column,
      row,
      xMm: round(format.marginLeftMm + column * format.pitchXMm),
      yMm: round(format.marginTopMm + row * format.pitchYMm),
    });
  }
  return positions;
}

export function pageCount(
  format: LabelFormat,
  count: number,
  skip = 0,
): number {
  const positions = layoutLabels(format, count, skip);
  return positions.length === 0 ? 0 : positions[positions.length - 1]!.page + 1;
}

export type LabelContentPlan = {
  paddingMm: number;
  qrMm: number;
  /** QR right of the text (wide labels) or text below the QR (tall labels). */
  direction: "row" | "column";
  showLogo: boolean;
  titleFontPt: number;
  metaFontPt: number;
  maxMetaLines: number;
};

/** How much fits on one label of the given size. */
export function labelContentPlan(format: LabelFormat): LabelContentPlan {
  const width = format.labelWidthMm;
  const height = format.labelHeightMm;
  const paddingMm = height < 25 ? 1.5 : 2.5;
  const direction = height > width ? "column" : "row";
  const innerHeight = height - paddingMm * 2;
  const innerWidth = width - paddingMm * 2;
  const qrMm = round(
    direction === "column"
      ? Math.min(innerWidth, innerHeight * 0.55)
      : Math.min(innerHeight, innerWidth * 0.45),
  );
  const showLogo = height >= 28 && width >= 60;
  const titleFontPt = height < 25 ? 6.5 : height < 32 ? 8 : 10;
  const metaFontPt = height < 25 ? 5 : height < 32 ? 6 : 7.5;
  const textHeightMm =
    direction === "column" ? innerHeight - qrMm - 2 : innerHeight;
  // 1 pt ≈ 0.353 mm; line height 1.2, title takes two lines at most.
  const lineMm = metaFontPt * 0.353 * 1.2;
  const titleMm = titleFontPt * 0.353 * 1.2 * 2;
  const logoMm = showLogo ? 6 : 0;
  const maxMetaLines = Math.max(
    0,
    Math.min(4, Math.floor((textHeightMm - titleMm - logoMm) / lineMm)),
  );
  return {
    paddingMm,
    qrMm,
    direction,
    showLogo,
    titleFontPt,
    metaFontPt,
    maxMetaLines,
  };
}

// ---------------------------------------------------------------------------
// QR payloads

export type LabelQrMode = "app" | "web";

export function assetDeepLink(assetId: string): string {
  return `${APP_SCHEME}://asset/${encodeURIComponent(assetId.toLowerCase())}`;
}

export function rackDeepLink(rackName: string): string {
  return `${APP_SCHEME}://infrastructure?rack=${encodeURIComponent(rackName.trim())}`;
}

/** Web fallback: the web app opens the asset list filtered to this asset. */
export function assetWebLink(baseUrl: string, assetId: string): string {
  const url = new URL(baseUrl);
  url.search = "";
  url.hash = "";
  url.searchParams.set("asset", assetId.toLowerCase());
  return url.toString();
}

export function rackWebLink(baseUrl: string, rackName: string): string {
  const url = new URL(baseUrl);
  url.search = "";
  url.hash = "";
  url.searchParams.set("rack", rackName.trim());
  return url.toString();
}

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Web link of a stock article: the web app opens the Lager article list. */
export function inventoryWebLink(baseUrl: string, itemId: string): string {
  const url = new URL(baseUrl);
  url.search = "";
  url.hash = "";
  url.searchParams.set("inventory", itemId.toLowerCase());
  return url.toString();
}

/** «?inventory=<uuid>» from a stock article label link, if valid. */
export function inventoryIdFromSearch(search: string): string | null {
  const value = new URLSearchParams(search).get("inventory")?.trim() ?? "";
  return UUID_PATTERN.test(value) ? value.toLowerCase() : null;
}

/** «?asset=<uuid>» from a web fallback link, if valid. */
export function assetIdFromSearch(search: string): string | null {
  const value = new URLSearchParams(search).get("asset")?.trim() ?? "";
  return UUID_PATTERN.test(value) ? value.toLowerCase() : null;
}

/** «?rack=<name>» from a web fallback link, if present. */
export function rackFromSearch(search: string): string | null {
  const value = new URLSearchParams(search).get("rack")?.trim() ?? "";
  return value && value.length <= 120 ? value : null;
}

// ---------------------------------------------------------------------------
// Label items and document

export type LabelItem = {
  /** Unique key, e.g. «asset:<id>» or «rack:<name>». */
  key: string;
  title: string;
  /** Short lines such as «Inventar: 4711». */
  meta: string[];
  qrText: string;
};

export type LabelAsset = {
  id: string;
  name: string;
  assetTag: string | null;
  inventoryNumber: string | null;
  serialNumber?: string | null;
};

function present(value: string | null | undefined): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

export function assetLabelItem(
  asset: LabelAsset,
  mode: LabelQrMode,
  baseUrl: string,
): LabelItem {
  return {
    key: `asset:${asset.id}`,
    title: asset.name.trim() || "Asset",
    meta: [
      present(asset.inventoryNumber)
        ? `Inventar: ${asset.inventoryNumber.trim()}`
        : null,
      present(asset.assetTag) ? `Tag: ${asset.assetTag.trim()}` : null,
      present(asset.serialNumber) ? `S/N: ${asset.serialNumber.trim()}` : null,
    ].filter(present),
    qrText:
      mode === "app"
        ? assetDeepLink(asset.id)
        : assetWebLink(baseUrl, asset.id),
  };
}

export type LabelInventoryItem = {
  id: string;
  name: string;
  articleNumber: string | null;
  /** Shown as «Lagerort», e.g. «Wandschrank ICT». */
  locationName: string | null;
};

/** Label of a stock article; the QR code is always the web link. */
export function inventoryLabelItem(
  item: LabelInventoryItem,
  baseUrl: string,
): LabelItem {
  return {
    key: `inventory:${item.id}`,
    title: item.name.trim() || "Artikel",
    meta: [
      present(item.articleNumber)
        ? `Artikel: ${item.articleNumber.trim()}`
        : null,
      present(item.locationName)
        ? `Lagerort: ${item.locationName.trim()}`
        : null,
    ].filter(present),
    qrText: inventoryWebLink(baseUrl, item.id),
  };
}

export function rackLabelItem(
  rack: { name: string; locationName: string | null; deviceCount: number },
  mode: LabelQrMode,
  baseUrl: string,
): LabelItem {
  return {
    key: `rack:${rack.locationName ?? ""}:${rack.name}`,
    title: `Rack ${rack.name.trim()}`,
    meta: [
      present(rack.locationName) ? rack.locationName.trim() : null,
      `${rack.deviceCount} ${rack.deviceCount === 1 ? "Gerät" : "Geräte"}`,
    ].filter(present),
    qrText:
      mode === "app"
        ? rackDeepLink(rack.name)
        : rackWebLink(baseUrl, rack.name),
  };
}

export function escapeHtml(value: string): string {
  return value.replace(
    /[&<>'"]/g,
    (character) =>
      ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "'": "&#039;",
        '"': "&quot;",
      })[character] ?? character,
  );
}

function usableLogoUrl(value: string | null | undefined): string | null {
  if (!value) return null;
  try {
    const url = new URL(value);
    return url.protocol === "https:" ? url.toString() : null;
  } catch {
    return null;
  }
}

export type LabelDocumentInput = {
  format: LabelFormat;
  items: LabelItem[];
  skip?: number;
  /** QR codes as SVG markup, by item key. */
  qrSvgs: ReadonlyMap<string, string>;
  branding?: { name: string | null; logoUrl: string | null } | undefined;
  autoPrint?: boolean;
};

function round(value: number): number {
  return Math.round(value * 100) / 100;
}

/** Keeps only the <svg> element (no scripts, no XML prolog). */
function safeSvg(markup: string | undefined): string {
  if (!markup) return "";
  const match = markup.match(/<svg[\s\S]*<\/svg>/i);
  if (!match) return "";
  return /<script|on\w+\s*=/i.test(match[0]) ? "" : match[0];
}

export function buildLabelDocument(input: LabelDocumentInput): string {
  const { format, items } = input;
  const plan = labelContentPlan(format);
  const positions = layoutLabels(format, items.length, input.skip ?? 0);
  const logoUrl = plan.showLogo ? usableLogoUrl(input.branding?.logoUrl) : null;
  const brandName = input.branding?.name?.trim() ?? "";
  const pages = new Map<number, string[]>();
  positions.forEach((position, index) => {
    const item = items[index]!;
    const meta = item.meta
      .slice(0, plan.maxMetaLines)
      .map((line) => `<span class="meta">${escapeHtml(line)}</span>`)
      .join("");
    const brand =
      plan.showLogo && (logoUrl || brandName)
        ? `<div class="brand">${
            logoUrl
              ? `<img alt="${escapeHtml(brandName)}" src="${escapeHtml(logoUrl)}" />`
              : `<span>${escapeHtml(brandName)}</span>`
          }</div>`
        : "";
    const label = `<div class="label" style="left:${position.xMm}mm;top:${position.yMm}mm"><div class="qr">${safeSvg(input.qrSvgs.get(item.key))}</div><div class="text">${brand}<strong class="title">${escapeHtml(item.title)}</strong>${meta}</div></div>`;
    pages.set(position.page, [...(pages.get(position.page) ?? []), label]);
  });
  const body = [...pages.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, labels]) => `<section class="page">${labels.join("")}</section>`)
    .join("");
  const css = `
@page { size: ${format.pageWidthMm}mm ${format.pageHeightMm}mm; margin: 0; }
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: #fff; color: #000; }
body { font-family: "Inter", "Helvetica Neue", Arial, sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.page { position: relative; width: ${format.pageWidthMm}mm; height: ${format.pageHeightMm}mm; overflow: hidden; page-break-after: always; break-after: page; }
.page:last-child { page-break-after: auto; break-after: auto; }
.label { position: absolute; width: ${format.labelWidthMm}mm; height: ${format.labelHeightMm}mm; padding: ${plan.paddingMm}mm; display: flex; flex-direction: ${plan.direction}; gap: ${plan.direction === "row" ? 1.8 : 1.2}mm; align-items: ${plan.direction === "row" ? "center" : "stretch"}; overflow: hidden; }
.qr { flex: none; width: ${plan.qrMm}mm; height: ${plan.qrMm}mm; ${plan.direction === "column" ? "align-self: center;" : ""} }
.qr svg { display: block; width: 100%; height: 100%; }
.text { min-width: 0; flex: 1; display: flex; flex-direction: column; justify-content: center; gap: 0.4mm; }
.brand { height: 5mm; margin-bottom: 0.8mm; display: flex; align-items: center; }
.brand img { max-height: 5mm; max-width: 100%; object-fit: contain; }
.brand span { font-size: ${plan.metaFontPt}pt; font-weight: 700; letter-spacing: 0.02em; text-transform: uppercase; }
.title { font-size: ${plan.titleFontPt}pt; line-height: 1.15; font-weight: 800; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow-wrap: anywhere; }
.meta { font-size: ${plan.metaFontPt}pt; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
@media screen { body { background: #e5e7eb; padding: 12px; } .page { background: #fff; margin: 0 auto 12px; box-shadow: 0 1px 4px rgba(0,0,0,.25); } .label { outline: 0.2mm dashed #cbd5e1; } }
`;
  return `<!doctype html>
<html lang="de-CH">
<head>
  <meta charset="utf-8" />
  <title>Asset-Etiketten · ${escapeHtml(format.name)}</title>
  <style>${css}</style>
</head>
<body>
${body}
${input.autoPrint === false ? "" : `<script>window.onload=()=>{const imgs=[...document.images];Promise.all(imgs.map(i=>i.complete?null:new Promise(r=>{i.onload=i.onerror=r;}))).then(()=>window.print());};</script>`}
</body>
</html>`;
}
